import fs from 'node:fs';
import path from 'node:path';

const root = process.cwd();
const replacements = [];
const editLines = (relative, changes) => {
    const file = path.join(root, relative);
    const original = fs.readFileSync(file, 'utf8');
    const newline = original.includes('\r\n') ? '\r\n' : '\n';
    const lines = original.split(/\r?\n/);
    for (const [prefix, replacement] of changes) {
        const indexes = lines.map((line, index) => line.startsWith(prefix) ? index : -1).filter(index => index >= 0);
        if (indexes.length !== 1) throw new Error(`${relative}: ${prefix} matched ${indexes.length} lines`);
        lines[indexes[0]] = replacement;
        replacements.push({ file: relative, prefix });
    }
    fs.writeFileSync(file, lines.join(newline), 'utf8');
};
const replaceOnce = (relative, oldText, newText) => {
    const file = path.join(root, relative);
    const original = fs.readFileSync(file, 'utf8');
    const count = original.split(oldText).length - 1;
    if (count !== 1) throw new Error(`${relative}: insertion anchor matched ${count} times`);
    fs.writeFileSync(file, original.replace(oldText, newText), 'utf8');
    replacements.push({ file: relative, prefix: 'insert before current UI027 evidence section' });
};

